import path from "node:path";
import type { PortosaurOptions } from "./siteConfig.ts";

/**
 * Next.js root generator (Fumadocs rebuild, Phase 1).
 *
 * The CLI generates a thin Next.js project root in `.portosaur/` (see the
 * Phase 1 contracts, §3): `next.config.mjs`, `source.config.ts`,
 * `lib/source.ts`, `lib/config.ts`, and the `app/` route files. The
 * generated files are thin wrappers — every real implementation lives in
 * `@portosaur/core` and is imported from there. The CLI never imports
 * `@portosaur/core` itself.
 *
 * The functions here only build the file *contents* (pure string builders).
 * The runner (`writeNextRoot`) resolves the options and writes the files.
 *
 * Two shapes are verified against the fumadocs-mdx source (15.6.2):
 *
 * - The global `mdxOptions` in `source.config.ts` (`defineConfig`) apply
 *   to macro-defined collections too — the MDX builder falls back to
 *   `config.global.mdxOptions` for collections without collection-level
 *   options (`loaders/mdx/build-default.ts`).
 * - `valueToExport` names become named exports of the compiled MDX module,
 *   reachable as `page.data._exports.<name>` (`runtime/server.ts`).
 */

export interface NextRootArgs {
  projectDir: string;
  outDir: string;
  mtime: number;
  /**
   * Whether the blog directory holds at least one post. When false
   * only the `/blog/[slug]` route is skipped: under
   * `output: "export"` a dynamic route whose
   * `generateStaticParams()` returns [] fails the build, so a
   * post-less blog must have no post route. The blog index and
   * authors pages are static routes — they always exist and render
   * their empty state (`/blog/` with no posts, `/blog/authors/`
   * from `authors.yml` alone).
   */
  hasBlogPosts: boolean;
  /**
   * Hosts allowed to reach Next.js dev resources (HMR, `/_next/*`
   * internals) in addition to Next's own defaults (`localhost`,
   * `**.localhost`, and the hostname the dev server started with).
   * Next 15.2+ blocks anything else with a 403 — so without this,
   * `porto dev --host 0.0.0.0` serves pages fine but hot reload is
   * dead from `127.0.0.1` and from LAN devices (phones). Resolved
   * by the runner: `127.0.0.1` plus the machine's LAN IPv4
   * addresses. Emitted as `allowedDevOrigins`, a dev-only option
   * `next build` ignores.
   */
  devOrigins: string[];
}

/**
 * The header comment stamped on every generated file (except
 * `next-env.d.ts`, which Next.js owns, and `tsconfig.json`, which carries
 * it as a JSONC comment).
 */
function header(mtime: number): string {
  // The value is the porto.yml mtime, not a generation timestamp:
  // stamping it here busts downstream caches whenever the config
  // changes (the file content changes, so Next rebuilds).
  return `// Auto-generated by portosaur — do not edit\n// Config mtime: ${mtime}\n`;
}

/**
 * A content dir as the generated root sees it: the `.portosaur/` project
 * root sits one level below the user project, so every user dir is
 * `../<dir>`. The `defineDocs`/`defineCollections` macros require `dir`
 * to be a string literal, so the CLI writes the literal path here.
 */
function rootRelativeDir(dir: string): string {
  return `../${dir.replace(/\\/g, "/")}`;
}

/**
 * The export output dir as Next sees it: relative to the generated
 * root (`.portosaur/`). Shared by the config builder (which emits
 * it as `distDir`) and the tsconfig builder (whose type globs are
 * derived from it — see `buildTsConfigContent`).
 */
function distDirOf({
  projectDir,
  outDir,
}: Pick<NextRootArgs, "projectDir" | "outDir">): string {
  // Relative to the generated root — see the doc comment on
  // `buildNextConfigContent` below.
  return path.relative(path.join(projectDir, ".portosaur"), outDir);
}

/**
 * Builds the contents of the generated `.portosaur/next.config.mjs`.
 *
 * With `output: 'export'` and a custom `distDir`, Next.js writes the
 * static export to `distDir` while build artifacts and the Turbopack
 * cache stay in `.next` (verified in Next 16's `export/utils.js`:
 * `hasCustomExportOutput` / `getBuildDistDir`).
 *
 * `distDir` MUST be relative to the generated root (`.portosaur/`):
 * Next joins it onto the project dir with `path.join`, which does
 * not treat a leading `/` as an anchor — an absolute path gets
 * mangled into `.portosaur/home/.../build` and the export lands in
 * a junk directory inside the generated root. The default output
 * dir is therefore `../build`, not the absolute path.
 * `basePath` takes the base URL without its trailing slash.
 *
 * `allowedDevOrigins` is a dev-only option (`next build` ignores
 * it): Next's dev server allows HMR and `/_next/*` requests only
 * from `localhost`, `**.localhost`, the started hostname, and this
 * list (verified in Next 16's `block-cross-site-dev.js`). Without
 * it, `porto dev --host 0.0.0.0` serves pages but hot reload is
 * blocked from `127.0.0.1` and LAN devices.
 */
export function buildNextConfigContent(
  options: PortosaurOptions,
  { projectDir, outDir, mtime, devOrigins }: NextRootArgs,
): string {
  const basePath =
    options.site.baseUrl === "/"
      ? ""
      : `\n  basePath: ${JSON.stringify(options.site.baseUrl.replace(/\/$/, ""))},`;
  const distDir = distDirOf({ projectDir, outDir });

  return `${header(mtime)}import { createMDX } from "fumadocs-mdx/next";

const withMDX = createMDX();

/** @type {import("next").NextConfig} */
const config = {
  output: "export",
  trailingSlash: true,
  reactStrictMode: true,
  images: { unoptimized: true },
  transpilePackages: ["@portosaur/core"],
  distDir: ${JSON.stringify(distDir)},${basePath}
  allowedDevOrigins: ${JSON.stringify(devOrigins)},
};

export default withMDX(config);
`;
}

/**
 * Builds the contents of the generated `.portosaur/source.config.ts`.
 *
 * Global MDX options only — the collections live in `lib/source.ts`
 * (macro pattern). The whole preset (Portosaur's remark/rehype plugins
 * in their order, `valueToExport`, and the Shiki light/dark themes for
 * the site's color scheme) comes from the core's `portosaurMdxOptions`
 * builder: the npm plugins are imported inside the core package, where
 * they are direct dependencies and resolve. Importing them here, from
 * the generated root, would NOT resolve — the user project's
 * `node_modules` only holds its direct dependencies.
 */
export function buildSourceConfigContent(
  options: PortosaurOptions,
  mtime: number,
): string {
  // Content directories for relative file links (`./sibling.mdx`):
  // the same directories the docs and blog collections read, as
  // absolute paths, with the URL section each one serves under.
  // `notesDir` / `notesRoute` are already mode-aware (docs mode →
  // the docs dir, portfolio mode → the notes dir).
  const contentDirs = [
    {
      dir: path.join(options.projectDir, options.site.notesDir),
      route: options.site.notesRoute,
    },
    {
      dir: path.join(options.projectDir, options.site.blogDir),
      route: options.site.blogRoute,
    },
  ];
  return `${header(mtime)}import { defineConfig } from "fumadocs-mdx/config";
import { portosaurMdxOptions } from "@portosaur/core/mdx";

export default defineConfig({
  mdxOptions: portosaurMdxOptions({
    userVars: ${JSON.stringify(options.userVars ?? {}, null, 2)},
    onMissingVar: ${JSON.stringify(options.site.content.onMissingVar)},
    onMissingEnv: ${JSON.stringify(options.site.content.onMissingEnv)},
    onDuplicateH2: ${JSON.stringify(options.site.content.onDuplicateH2)},
    colorScheme: ${JSON.stringify(options.theme.colorScheme)},
    renderEmojiShortcodes: ${JSON.stringify(options.site.content.renderEmojiShortcodes)},
    mermaid: ${JSON.stringify(options.site.content.mermaid)},
    contentDirs: ${JSON.stringify(contentDirs)},
  }),
});
`;
}

/**
 * Builds the contents of the generated `.portosaur/lib/source.ts`.
 *
 * Macro pattern (official fumadocs-mdx shape): `defineDocs` +
 * `defineCollections` as top-level `const` initializers, with the schema,
 * slugs function, and page-tree transformers imported from
 * `@portosaur/core/lib/source`. The docs collection points at the notes
 * dir in portfolio mode and the docs dir in docs mode —
 * `options.site.notesDir` is already mode-aware. `postprocess` includes
 * the processed Markdown so the llms routes can render each page.
 */
export function buildLibSourceContent(
  options: PortosaurOptions,
  mtime: number,
): string {
  return `${header(mtime)}import { loader, llms } from "fumadocs-core/source";
import { defineDocs, defineCollections } from "fumadocs-mdx/macro";
import { metaSchema } from "fumadocs-core/source/schema";
import {
  portoDocSchema,
  portoBlogSchema,
  portoSlugs,
  portoTreeTransformers,
} from "@portosaur/core/lib/source";

const docs = defineDocs({
  dir: ${JSON.stringify(rootRelativeDir(options.site.notesDir))},
  docs: {
    schema: portoDocSchema,
    postprocess: {
      includeProcessedMarkdown: true,
    },
  },
  meta: {
    schema: metaSchema,
  },
});

const blog = defineCollections({
  type: "doc",
  dir: ${JSON.stringify(rootRelativeDir(options.site.blogDir))},
  schema: portoBlogSchema,
  postprocess: {
    includeProcessedMarkdown: true,
  },
});

// See https://fumadocs.dev/docs/headless/source-api for more info
export const source = loader({
  baseUrl: ${JSON.stringify(`/${options.site.notesRoute}`)},
  source: docs.toFumadocsSource(),
  slugs: portoSlugs,
  pageTree: {
    sort: { by: "path", options: { numeric: true } },
    transformers: portoTreeTransformers,
  },
});

export const blogSource = loader({
  baseUrl: ${JSON.stringify(`/${options.site.blogRoute}`)},
  source: blog.toFumadocsSource(),
  slugs: portoSlugs,
});

export const docsLlms = llms(source, {
  renderPage: async (page) =>
    \`# \${page.data.title ?? page.url} (\${page.url})\\n\\n\${await page.data.getText("processed")}\`,
  // link to the files under \`/llms.mdx\`
  renderUrl: (item) =>
    /^\\/.*\\.(md|txt)$/.test(item.url) ? \`/llms.mdx\${item.url}\` : item.url,
});
`;
}

/**
 * Builds the contents of the generated `.portosaur/lib/config.ts`.
 *
 * The resolved `PortosaurOptions` object, embedded as JSON and checked
 * against the core package's type at `next build` time — that is the
 * drift alarm between the engine's shape and the core's copy.
 */
export function buildLibConfigContent(
  options: PortosaurOptions,
  mtime: number,
): string {
  return `${header(mtime)}import type { PortosaurOptions } from "@portosaur/core/lib/config";

export const config: PortosaurOptions = ${JSON.stringify(options, null, 2)};
`;
}

/**
 * Builds the contents of the generated `.portosaur/postcss.config.mjs`
 * (Tailwind v4 PostCSS plugin — the create-fumadocs-app scaffold shape).
 */
export function buildPostcssConfigContent(mtime: number): string {
  return `${header(mtime)}const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;
`;
}

/**
 * Builds the contents of the generated `.portosaur/tsconfig.json`
 * (the create-fumadocs-app scaffold shape, with `@/*` mapped to the
 * generated root).
 *
 * The type globs cover BOTH the export distDir and `.next`, because
 * dev and build ask Next for different ones (verified in Next 16):
 * `next dev` passes the configured `distDir` to
 * `writeConfigurationDefaults` (setup-dev-bundler.js), while
 * `next build` passes `getBuildDistDir(config)` (type-check.js) —
 * which is `.next` whenever `output: 'export'` has a custom
 * distDir, because build artifacts stay in `.next` and only the
 * export goes to the custom dir (export/utils.js). Emitting only
 * one set makes the other mode rewrite the file on every run —
 * and the rewrite is wiped by the next regeneration anyway, so
 * the "reconfigured your tsconfig.json" message never goes away.
 * Glob patterns use forward slashes on every platform.
 */
export function buildTsConfigContent(args: NextRootArgs): string {
  const { mtime } = args;
  const distDirPosix = distDirOf(args).replace(/\\/g, "/");

  return `${header(mtime)}{
  "compilerOptions": {
    "target": "ESNext",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "allowImportingTsExtensions": true,
    "skipLibCheck": true,
    "strict": true,
    "forceConsistentCasingInFileNames": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "react-jsx",
    "incremental": true,
    "paths": {
      "@/*": ["./*"]
    },
    "plugins": [
      {
        "name": "next"
      }
    ]
  },
  "include": [
    "next-env.d.ts",
    "**/*.ts",
    "**/*.tsx",
    "${distDirPosix}/types/**/*.ts",
    "${distDirPosix}/dev/types/**/*.ts",
    ".next/types/**/*.ts",
    ".next/dev/types/**/*.ts"
  ],
  "exclude": ["node_modules"]
}
`;
}

/**
 * The contents of the generated `.portosaur/next-env.d.ts`. Next.js
 * regenerates this file on `next dev` / `next build`. Writing it upfront
 * matches the scaffold so the first run has it.
 */
export function buildNextEnvContent(): string {
  return `/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/layout.tsx`.
 *
 * The root layout imports the core's global CSS (the import lives here,
 * not in the core package) and renders the core's `RootLayout`, which owns
 * `<html>`/`<body>`, the theme pre-paint script, and the config context.
 * The user's `theme.custom_css` files are imported here too, resolved
 * relative to the generated root's `app/` directory.
 *
 * The metadata is a `generateMetadata` function, not a static object:
 * the social card's dimensions are read from the image file at build
 * time (via the core's `image-size` helper). The theme color lives
 * in a `generateViewport` export instead: Next 16 ignores
 * `metadata.themeColor` (it warns "unsupported metadata" and drops
 * it) and only renders the tag from the viewport. The viewport also
 * carries `viewportFit: "cover"`, which lets the page extend under
 * notches and gesture bars so `env(safe-area-inset-*)` reports real
 * values instead of 0 — the navbar, the floating arrow, and the
 * footer all read those insets. The manifest link
 * is emitted only when `site.pwa.enable` is on — with the PWA off
 * there is no manifest file to link to.
 */
export function buildRootLayoutContent(
  options: PortosaurOptions,
  { projectDir, mtime }: NextRootArgs,
): string {
  const customCss = options.theme.customCss;
  const customPaths = customCss
    ? Array.isArray(customCss)
      ? customCss
      : [customCss]
    : [];
  const appDir = path.join(projectDir, ".portosaur", "app");
  const customImports = customPaths
    .map((entry) => {
      const abs = path.resolve(projectDir, entry);
      const rel = path.relative(appDir, abs).replace(/\\/g, "/");
      const specifier = rel.startsWith(".") ? rel : `./${rel}`;
      return `import ${JSON.stringify(specifier)};`;
    })
    .join("\n");
  const manifestField =
    options.site.pwa?.enable !== false
      ? `    manifest: absoluteImageUrl(config, "/manifest.webmanifest"),\n`
      : "";

  return `${header(mtime)}import type { Metadata, Viewport } from "next";
import type { ReactNode } from "react";
import { config } from "@/lib/config";
import { siteIcons } from "../site-icons";
import { RootLayout } from "@portosaur/core/components/layouts/root-layout";
import { getCssVar } from "@portosaur/core/lib/assets";
import {
  absoluteImageUrl,
  siteOriginOf,
  sizedSocialImage,
} from "@portosaur/core/lib/metadata";
import "@portosaur/core/css/global.css";
${customImports ? `${customImports}\n` : ""}
export async function generateMetadata(): Promise<Metadata> {
  const card = await sizedSocialImage(
    config,
    config.site.socialCard || "img/social-card.jpeg",
  );
  return {
    metadataBase: new URL(siteOriginOf(config)),
    title: {
      default: config.site.title,
      template: \`%s | \${config.site.title}\`,
    },
    description: config.site.tagline,
    icons: {
      icon: [
        {
          url: absoluteImageUrl(config, "/favicon/favicon.ico"),
          sizes: "32x32",
        },
        {
          url: absoluteImageUrl(config, "/favicon/icon-192x192.png"),
          sizes: "192x192",
          type: "image/png",
        },
      ],
      apple: [
        {
          url: absoluteImageUrl(config, "/favicon/apple-touch-icon.png"),
          sizes: "180x180",
        },
      ],
    },
${manifestField}    appleWebApp: {
      capable: true,
      statusBarStyle: "default",
      title: config.site.title,
    },
    openGraph: {
      type: "website",
      title: config.site.title,
      description: config.site.tagline,
      images: [card],
    },
    twitter: {
      card: "summary_large_image",
      title: config.site.title,
      description: config.site.tagline,
      images: [card.url],
    },
  };
}

export async function generateViewport(): Promise<Viewport> {
  const themeColor = getCssVar("--porto-color-bg", config.cssFiles ?? []);
  if (!themeColor) {
    return { viewportFit: "cover" };
  }
  return { themeColor, viewportFit: "cover" };
}

export default function Layout({ children }: { children: ReactNode }) {
  return (
    <RootLayout config={config} icons={siteIcons}>
      {children}
    </RootLayout>
  );
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/page.tsx`.
 *
 * Docs mode renders the core's docs home (hero + feature cards from
 * `config.docsHome`). Portfolio mode renders the core's portfolio
 * home (hero, about, projects, experience, contact from
 * `config.homePage`). The title follows the OG rule (Astro
 * `index.astro`): "Home" in docs mode, "Me" in portfolio mode,
 * suffixed with `| {site title}`.
 *
 * The suffix is baked in as an absolute title instead of relying on
 * the root layout's template: Next's `accumulateMetadata` only
 * stashes a layer's title template for items before the last two
 * (the leaf layout + leaf page), and for the root route the layout
 * IS one of the last two — so the root template never applies to
 * the home page itself (verified in Next 16's `resolve-metadata.js`).
 * Nested pages are unaffected.
 */
export function buildHomePageContent(
  options: PortosaurOptions,
  mtime: number,
): string {
  const title = options.siteMode === "docs" ? "Home" : "Me";
  const absoluteTitle = `${title} | ${options.site.title}`;
  if (options.siteMode === "docs") {
    return `${header(mtime)}import { config } from "@/lib/config";
import { DocsHomePage } from "@portosaur/core/components/pages/docs-home-page";
import type { Metadata } from "next";

export const metadata: Metadata = { title: { absolute: ${JSON.stringify(absoluteTitle)} } };

export default function Page() {
  return <DocsHomePage config={config} />;
}
`;
  }

  return `${header(mtime)}import { config } from "@/lib/config";
import { PortfolioHomePage } from "@portosaur/core/components/pages/portfolio-home-page";
import type { Metadata } from "next";

export const metadata: Metadata = { title: { absolute: ${JSON.stringify(absoluteTitle)} } };

export default function Page() {
  return <PortfolioHomePage config={config} />;
}
`;
}

/**
 * Builds the contents of a docs-frame layout
 * (`.portosaur/app/docs/layout.tsx`, and
 * `app/notes/(with-sidebar)/layout.tsx` in portfolio mode — notes
 * share the docs layout frame, scoped to the detail routes by the
 * route group so the index keeps its own shell).
 */
export function buildDocsLayoutContent(mtime: number): string {
  return `${header(mtime)}import type { ReactNode } from "react";
import { source } from "@/lib/source";
import { config } from "@/lib/config";
import { DocsLayout } from "@portosaur/core/components/layouts/docs-layout";

export default function Layout({ children }: { children: ReactNode }) {
  return (
    <DocsLayout config={config} tree={source.getPageTree()}>
      {children}
    </DocsLayout>
  );
}
`;
}

/**
 * Builds the contents of a doc detail page
 * (`.portosaur/app/docs/[[...slug]]/page.tsx`, and
 * `app/notes/(with-sidebar)/[...slug]/page.tsx` in portfolio
 * mode). The loaded page goes to the core's `DocPage`, which
 * renders the hoisted H1 (from
 * `page.data._exports.__portoContentTitle`), the MDX body,
 * pagination, and the doc footer.
 *
 * The docs route is an OPTIONAL catch-all: the collection's root page
 * (the README) renders at `/docs/` through it. The notes route is a
 * REQUIRED catch-all: `/notes/` is owned by the notes index page
 * (`app/notes/page.tsx`), and Next.js forbids a static route at the
 * same specificity as an optional catch-all. The required catch-all's
 * `generateStaticParams` therefore drops the empty root slug — a
 * root README in a user's notes dir has no detail page.
 */
export function buildDocPageContent(
  route: string,
  mtime: number,
  catchAll: "optional" | "required" = "optional",
): string {
  const slugParam = catchAll === "optional" ? "[[...slug]]" : "[...slug]";
  const staticParams =
    catchAll === "optional"
      ? "return source.generateParams();"
      : "return source.generateParams().filter((p) => p.slug.length > 0);";
  return `${header(mtime)}import { source } from "@/lib/source";
import { config } from "@/lib/config";
import { DocPage } from "@portosaur/core/components/pages/doc-page";
import { docPageTitles, docFileTitle } from "@portosaur/core/lib/docPage";
import { sizedSocialImage } from "@portosaur/core/lib/metadata";
import { createRelativeLink } from "@portosaur/core/components/mdx";
import { CONTENT_TITLE_KEY } from "@portosaur/core/plugins/remarkContentTitle";
import { notFound } from "next/navigation";
import type { Metadata } from "next";

export default async function Page(props: PageProps<"/${route}/${slugParam}">) {
  const params = await props.params;
  const page = source.getPage(params.slug);
  if (!page) {
    notFound();
  }
  // Edit URL: the configured edit base + the file path relative to
  // the content dir (the edit base already includes the content dir).
  const editBase = config.site.editUrl;
  const editUrl = editBase
    ? (editBase.endsWith("/") ? editBase : editBase + "/") + page.path
    : undefined;
  return (
    <DocPage
      config={config}
      page={page}
      tree={source.getPageTree()}
      editUrl={editUrl}
      components={{ a: createRelativeLink(source, page) }}
    />
  );
}

export async function generateStaticParams() {
  ${staticParams}
}

export async function generateMetadata(
  props: PageProps<"/${route}/${slugParam}">,
): Promise<Metadata> {
  const params = await props.params;
  const page = source.getPage(params.slug);
  if (!page) {
    notFound();
  }
  // Metadata title rule (Docusaurus behavior, same as the visible
  // heading): frontmatter title ?? content H1 ?? file-base fallback.
  // The hoisted H1 reaches the page as a named MDX export
  // (\`valueToExport\`), available directly on eager collections.
  const contentTitle =
    (page.data._exports as Record<string, unknown> | undefined)?.[
      CONTENT_TITLE_KEY
    ] ?? null;
  const { metaTitle } = docPageTitles(
    page.data,
    contentTitle as { text: string; slug: string } | null,
    docFileTitle(page.path),
  );
  // A frontmatter image is this page's social preview, overriding
  // the site-wide card from the root layout. Pages without one
  // inherit the site card.
  const image = page.data.image;
  if (image) {
    const social = await sizedSocialImage(config, image);
    return {
      title: metaTitle,
      description: page.data.desc,
      openGraph: { images: [social] },
      twitter: { images: [social.url] },
    };
  }
  return {
    title: metaTitle,
    description: page.data.desc,
  };
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/notes/page.tsx`
 * (the notes index at `/notes/`). It exists in both modes — in docs mode
 * the notes collection IS the docs collection, so the index lists the
 * docs pages as note cards.
 */
export function buildNotesIndexContent(mtime: number): string {
  return `${header(mtime)}import { source } from "@/lib/source";
import { config } from "@/lib/config";
import {
  NotesIndexPage,
  type NoteCardPage,
} from "@portosaur/core/components/pages/notes-index-page";
import { docPageTitles, docFileTitle } from "@portosaur/core/lib/docPage";
import { pageHref } from "@portosaur/core/lib/pageUrl";
import { CONTENT_TITLE_KEY } from "@portosaur/core/plugins/remarkContentTitle";
import type { Metadata } from "next";

export function generateMetadata(): Metadata {
  const route = config.site.notesRoute;
  return { title: route.charAt(0).toUpperCase() + route.slice(1) };
}

export default function Page() {
  // Top-level files + top-level dirs with an index, in filename
  // order (numeric-aware: 1 -, 2 -, 10 -). The root index itself
  // (no slugs) is not a card.
  const pages: NoteCardPage[] = source
    .getPages()
    .filter((page) => page.slugs.length === 1)
    .sort((a, b) =>
      a.path.localeCompare(b.path, undefined, { numeric: true }),
    )
    .map((page) => {
      const contentTitle =
        (page.data._exports as Record<string, unknown> | undefined)?.[
          CONTENT_TITLE_KEY
        ] ?? null;
      const { metaTitle } = docPageTitles(
        page.data,
        contentTitle as { text: string; slug: string } | null,
        docFileTitle(page.path),
      );
      return {
        title: metaTitle,
        href: pageHref(page.url),
        description: page.data.desc,
        icon: page.data.icon,
        color: page.data.color,
        slug: page.slugs.join("-"),
        draft: page.data.draft,
      };
    });
  return <NotesIndexPage config={config} pages={pages} />;
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/lib/blog.ts` —
 * helpers shared by the blog routes (index, post, authors): the
 * authors file, the post summaries, the date sort, the sidebar
 * list. The generated root owns this wiring (which loader, which
 * paths). The pure pieces live in `@portosaur/core/lib/blog`.
 */
export function buildLibBlogContent(mtime: number): string {
  return `${header(mtime)}import path from "node:path";
import { blogSource } from "./source";
import { config } from "./config";
import { loadBlogAuthors } from "@portosaur/core/lib/blog-server";
import { docFileTitle, docPageTitles } from "@portosaur/core/lib/docPage";
import { pageHref } from "@portosaur/core/lib/pageUrl";
import {
  resolveAuthor,
  sortPostsByDateDesc,
  type BlogAuthor,
} from "@portosaur/core/lib/blog";
import type { BlogIndexPost } from "@portosaur/core/components/pages/blog-index-page";
import type { BlogSidebarPost } from "@portosaur/core/components/pages/frame/BlogSidebar";
import { CONTENT_TITLE_KEY } from "@portosaur/core/plugins/remarkContentTitle";

/** The blog authors from \`blog/authors.yml\` ([] when absent). */
export function getBlogAuthors(): BlogAuthor[] {
  return loadBlogAuthors(
    path.join(config.projectDir, config.site.blogDir, "authors.yml"),
  );
}

/** Every blog post as an index summary (unsorted). */
export function getBlogPosts(): BlogIndexPost[] {
  return blogSource.getPages().map((page) => {
    const contentTitle =
      (page.data._exports as Record<string, unknown> | undefined)?.[
        CONTENT_TITLE_KEY
      ] ?? null;
    const { metaTitle } = docPageTitles(
      page.data,
      contentTitle as { text: string; slug: string } | null,
      docFileTitle(page.path),
    );
    return {
      id: page.slugs.join("/"),
      title: metaTitle,
      href: pageHref(page.url),
      date: page.data.date ?? null,
      description: page.data.desc,
      authors: page.data.authors,
      tags: page.data.tags,
    };
  });
}

/** Blog posts newest first (undated posts sort last, by id). */
export function getSortedBlogPosts(): BlogIndexPost[] {
  return sortPostsByDateDesc(getBlogPosts());
}

/** The year-grouped sidebar list, newest first. */
export function getBlogSidebarPosts(): BlogSidebarPost[] {
  return getSortedBlogPosts().map((post) => ({
    url: post.href,
    title: post.title,
    date: post.date ?? null,
  }));
}

/** The blog authors with their post counts (authors page only). */
export function getBlogAuthorsWithCounts(): BlogAuthor[] {
  const authors = getBlogAuthors();
  const posts = getBlogPosts();
  return authors.map((author) => ({
    ...author,
    count: posts.filter((post) =>
      (post.authors ?? []).some(
        (ref) => resolveAuthor(ref, authors).key === author.key,
      ),
    ).length,
  }));
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/blog/page.tsx`
 * (minimal blog index — the full blog lands in Phase 3).
 */
export function buildBlogIndexContent(mtime: number): string {
  return `${header(mtime)}import { config } from "@/lib/config";
import { getBlogAuthors, getBlogPosts } from "@/lib/blog";
import { BlogIndexPage } from "@portosaur/core/components/pages/blog-index-page";
import type { Metadata } from "next";

export function generateMetadata(): Metadata {
  return { title: "Blog" };
}

export default function Page() {
  return (
    <BlogIndexPage
      config={config}
      posts={getBlogPosts()}
      authors={getBlogAuthors()}
    />
  );
}
`;
}

/**
 * Builds the contents of the generated
 * `.portosaur/app/blog/[slug]/page.tsx` (minimal blog post — the full
 * blog lands in Phase 3).
 *
 * `generateParams()` returns `{ slug: string[] }` (catch-all shape), so
 * the params are mapped by hand for the single-segment `[slug]` route.
 * Blog posts are flat in Portosaur, so each post has exactly one slug.
 */
export function buildBlogPostContent(mtime: number): string {
  return `${header(mtime)}import { blogSource } from "@/lib/source";
import { config } from "@/lib/config";
import {
  getBlogAuthors,
  getBlogSidebarPosts,
  getSortedBlogPosts,
} from "@/lib/blog";
import { BlogPostPage } from "@portosaur/core/components/pages/blog-post-page";
import { docPageTitles, docFileTitle } from "@portosaur/core/lib/docPage";
import { sizedSocialImage } from "@portosaur/core/lib/metadata";
import { createRelativeLink } from "@portosaur/core/components/mdx";
import { pageHref } from "@portosaur/core/lib/pageUrl";
import { CONTENT_TITLE_KEY } from "@portosaur/core/plugins/remarkContentTitle";
import { notFound } from "next/navigation";
import type { Metadata } from "next";

export default async function Page(props: PageProps<"/blog/[slug]">) {
  const params = await props.params;
  const page = blogSource.getPage([params.slug]);
  if (!page) {
    notFound();
  }
  // Newer/older neighbors in the newest-first sort.
  const sorted = getSortedBlogPosts();
  const index = sorted.findIndex((post) => post.href === pageHref(page.url));
  const newer =
    index > 0
      ? { title: sorted[index - 1].title, href: sorted[index - 1].href }
      : null;
  const older =
    index >= 0 && index < sorted.length - 1
      ? { title: sorted[index + 1].title, href: sorted[index + 1].href }
      : null;
  return (
    <BlogPostPage
      config={config}
      post={{ ...page, date: page.data.date ?? null }}
      sidebarPosts={getBlogSidebarPosts()}
      newer={newer}
      older={older}
      authors={getBlogAuthors()}
      components={{ a: createRelativeLink(blogSource, page) }}
    />
  );
}

export async function generateStaticParams() {
  return blogSource.getPages().map((page) => ({ slug: page.slugs.join("/") }));
}

export async function generateMetadata(
  props: PageProps<"/blog/[slug]">,
): Promise<Metadata> {
  const params = await props.params;
  const page = blogSource.getPage([params.slug]);
  if (!page) {
    notFound();
  }
  // Metadata title rule (Docusaurus behavior, same as the visible
  // heading): frontmatter title ?? content H1 ?? file-base fallback.
  // The hoisted H1 reaches the page as a named MDX export
  // (\`valueToExport\`), available directly on eager collections.
  const contentTitle =
    (page.data._exports as Record<string, unknown> | undefined)?.[
      CONTENT_TITLE_KEY
    ] ?? null;
  const { metaTitle } = docPageTitles(
    page.data,
    contentTitle as { text: string; slug: string } | null,
    docFileTitle(page.path),
  );
  // A frontmatter image is this post's social preview, overriding
  // the site-wide card from the root layout. Posts without one
  // inherit the site card.
  const image = page.data.image;
  if (image) {
    const social = await sizedSocialImage(config, image);
    return {
      title: metaTitle,
      description: page.data.desc,
      openGraph: { images: [social] },
      twitter: { images: [social.url] },
    };
  }
  return {
    title: metaTitle,
    description: page.data.desc,
  };
}
`;
}

