/**
 * Builds the contents of the generated `.portosaur/app/sitemap.ts`.
 * Every URL gets its trailing slash via the core's `pageHref` helper.
 * The offline/redirect interstitials are not content, so they stay out
 * of the sitemap.
 */
export function buildSitemapContent(mtime: number): string {
  return `${header(mtime)}import type { MetadataRoute } from "next";
import { source, blogSource } from "@/lib/source";
import { config } from "@/lib/config";
import { pageHref } from "@portosaur/core/lib/pageUrl";

// Metadata routes compile to route handlers. With
// \`output: 'export'\` they must be marked static or the build
// fails at page-data collection.
export const dynamic = "force-static";

export default function sitemap(): MetadataRoute.Sitemap {
  const site = \`\${config.site.url.replace(/\\/$/, "")}\${
    config.site.baseUrl === "/" ? "" : config.site.baseUrl.replace(/\\/$/, "")
  }\`;
  const urls = new Set<string>(["/"]);
  for (const page of source.getPages()) {
    urls.add(page.url);
  }
  for (const page of blogSource.getPages()) {
    urls.add(page.url);
  }
  urls.add(\`/\${config.site.blogRoute}\`);
  urls.add(\`/\${config.site.notesRoute}\`);
  urls.add("/tasks");
  urls.add("/search");
  return [...urls].map((url) => ({ url: \`\${site}\${pageHref(url)}\` }));
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/robots.ts`.
 *
 * The `site.robots_txt.rules` entries use the config's snake-case keys
 * (`user_agent`, `allow`, `disallow`) and are mapped to Next's
 * `MetadataRoute.Robots` shape. `custom_lines` has no equivalent in
 * Next's robots convention — it is not emitted here (Phase 4
 * sitemap/robots verification item).
 */
export function buildRobotsContent(mtime: number): string {
  return `${header(mtime)}import type { MetadataRoute } from "next";
import { config } from "@/lib/config";

// Metadata routes compile to route handlers. With
// \`output: 'export'\` they must be marked static or the build
// fails at page-data collection.
export const dynamic = "force-static";

export default function robots(): MetadataRoute.Robots {
  const site = \`\${config.site.url.replace(/\\/$/, "")}\${
    config.site.baseUrl === "/" ? "" : config.site.baseUrl.replace(/\\/$/, "")
  }\`;
  if (!config.site.robotsTxt.enable) {
    return {
      rules: { userAgent: "*", disallow: "/" },
    };
  }
  const rules = config.site.robotsTxt.rules.map((rule) => ({
    userAgent: rule.user_agent ?? rule.userAgent ?? "*",
    allow: rule.allow,
    disallow: rule.disallow,
  }));
  return {
    rules: rules.length > 0 ? rules : { userAgent: "*", allow: "/" },
    sitemap: \`\${site}/sitemap.xml\`,
  };
}
`;
}

/**
 * Builds the contents of the generated `.portosaur/app/manifest.ts`
 * (Next's typed manifest — the file the browser reads for
 * installability, generated at build time from the resolved
 * config).
 *
 * The icon entries point at the generated favicon set (`/favicon/`),
 * the theme color comes from the scheme CSS, and the scope/start
 * URL follow the site base. Written only when `site.pwa.enable` is
 * on — with the PWA off there is no manifest at all.
 */
/**
 * Builds the contents of the generated `app/manifest.ts` (Next's
 * metadata route — it renders `manifest.webmanifest` at build
 * time, so the manifest always matches the current config).
 *
 * Shortcuts follow the site mode: docs sites get Documentation
 * and Blog; portfolio sites get Notes Vault, Blog, and Tasks
 * (only when `tasks.enable` is on). Screenshots come from
 * `static/screenshots/` — the home shot first, square images
 * skipped with a warning (browsers reject them for the install
 * carousel). The maskable icon is the padded square render, not
 * the circle crop.
 */
export function buildManifestContent(mtime: number): string {
  return `${header(mtime)}import fs from "node:fs";
import path from "node:path";
import type { MetadataRoute } from "next";
import { config } from "@/lib/config";
import { getCssVar } from "@portosaur/core/lib/assets";
import {
  localImageDimensions,
  staticDirsForConfig,
} from "@portosaur/core/lib/image-size";
import { withBase } from "@portosaur/core/lib/pageUrl";

// Metadata routes compile to route handlers. With
// \`output: 'export'\` they must be marked static or the build
// fails at page-data collection.
export const dynamic = "force-static";

const SCREENSHOT_TYPES: Record<string, string> = {
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
};

async function manifestScreenshots(
  staticDirs: string[],
): Promise<NonNullable<MetadataRoute.Manifest["screenshots"]>> {
  const names: string[] = [];
  const seen = new Set<string>();
  for (const dir of staticDirs) {
    let entries: string[];
    try {
      entries = fs.readdirSync(path.join(dir, "screenshots"));
    } catch {
      continue;
    }
    for (const name of entries) {
      if (
        !seen.has(name) &&
        SCREENSHOT_TYPES[path.extname(name).toLowerCase()]
      ) {
        seen.add(name);
        names.push(name);
      }
    }
  }
  // The home shot leads the install carousel; the rest follow
  // alphabetically.
  names.sort((a, b) => {
    const aHome = a.startsWith("home-") ? 0 : 1;
    const bHome = b.startsWith("home-") ? 0 : 1;
    return aHome - bHome || a.localeCompare(b);
  });
  const screenshots: NonNullable<MetadataRoute.Manifest["screenshots"]> = [];
  for (const name of names) {
    const dimensions = await localImageDimensions(
      \`screenshots/\${name}\`,
      staticDirs,
    );
    if (!dimensions) {
      continue;
    }
    if (dimensions.width === dimensions.height) {
      console.warn(
        \`PWA: skipping square screenshot screenshots/\${name} — browsers reject square images for the install carousel.\`,
      );
      continue;
    }
    screenshots.push({
      src: withBase(\`screenshots/\${name}\`, config.site.baseUrl),
      sizes: \`\${dimensions.width}x\${dimensions.height}\`,
      type: SCREENSHOT_TYPES[path.extname(name).toLowerCase()],
      form_factor: dimensions.width > dimensions.height ? "wide" : "narrow",
    });
  }
  return screenshots;
}

export default async function manifest(): Promise<MetadataRoute.Manifest> {
  const base =
    config.site.baseUrl === "/"
      ? "/"
      : config.site.baseUrl.endsWith("/")
        ? config.site.baseUrl
        : \`\${config.site.baseUrl}/\`;
  const themeColor = getCssVar("--porto-color-bg", config.cssFiles ?? []);
  const icon = (name: string) =>
    withBase(\`favicon/\${name}\`, config.site.baseUrl);
  const shortcutIcon = [
    {
      src: icon("icon-192x192.png"),
      sizes: "192x192",
      type: "image/png",
    },
  ];
  const shortcuts =
    config.siteMode === "docs"
      ? [
          {
            name: "Documentation",
            url: withBase("docs/", config.site.baseUrl),
            icons: shortcutIcon,
          },
          {
            name: "Blog",
            url: withBase("blog/", config.site.baseUrl),
            icons: shortcutIcon,
          },
        ]
      : [
          {
            name: "Notes Vault",
            url: withBase("notes/", config.site.baseUrl),
            icons: shortcutIcon,
          },
          {
            name: "Blog",
            url: withBase("blog/", config.site.baseUrl),
            icons: shortcutIcon,
          },
          ...(config.tasks.enable
            ? [
                {
                  name: "Tasks",
                  url: withBase("tasks/", config.site.baseUrl),
                  icons: shortcutIcon,
                },
              ]
            : []),
        ];
  const screenshots = await manifestScreenshots(staticDirsForConfig(config));
  return {
    name: config.site.title || "My Site",
    short_name: config.site.title || "My Site",
    description: config.site.tagline || "A Portosaur Site",
    id: \`\${base}?source=pwa\`,
    start_url: base,
    lang: "en",
    scope: base,
    display: "standalone",
    orientation: "natural",
    theme_color: themeColor ?? undefined,
    background_color: themeColor ?? undefined,
    icons: [
      {
        src: icon("icon-192x192.png"),
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: icon("icon-512x512.png"),
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: icon("icon-maskable-512x512.png"),
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts,
    ...(screenshots.length > 0 ? { screenshots } : {}),
  };
}
`;
}

/**
 * Builds the contents of the generated
 * `.portosaur/app/llms.txt/route.ts` (the create-fumadocs-app scaffold
 * pattern, served from the `docsLlms` export in `lib/source.ts`).
 */
export function buildLlmsTxtRouteContent(mtime: number): string {
  return `${header(mtime)}import { docsLlms } from "@/lib/source";

export const revalidate = false;

export async function GET() {
  return (await docsLlms.serve("/llms.txt"))!;
}
`;
}

/**
 * Builds the contents of the generated
 * `.portosaur/app/llms-full.txt/route.ts` (the create-fumadocs-app
 * scaffold pattern).
 */
export function buildLlmsFullTxtRouteContent(mtime: number): string {
  return `${header(mtime)}import { docsLlms } from "@/lib/source";

export const revalidate = false;

export async function GET() {
  return (await docsLlms.serve("/llms-full.txt"))!;
}
`;
}

/**
 * Builds the contents of the generated
 * `.portosaur/app/llms.mdx/[...path]/route.ts` (the
 * create-fumadocs-app scaffold pattern: per-page Markdown for LLM
 * consumption).
 */
export function buildLlmsMdxRouteContent(mtime: number): string {
  return `${header(mtime)}import { docsLlms } from "@/lib/source";

export const revalidate = false;
// other paths are 404s, never cached responses
export const dynamicParams = false;

export async function GET(_req: Request, { params }: RouteContext<"/llms.mdx/[...path]">) {
  const { path } = await params;
  return (await docsLlms.serve(\`/\${path.join("/")}\`)) ?? new Response(null, { status: 404 });
}

export async function generateStaticParams() {
  const params: { path: string[] }[] = [];
  for (const file of await docsLlms.files()) {
    // \`/llms.txt\` and \`/llms-full.txt\` have their own routes
    if (!/^\\/llms(-full)?\\.txt$/.test(file)) {
      params.push({ path: decodeURI(file).slice(1).split("/") });
    }
  }
  return params;
}
`;
}

/**
 * Builds the entire generated Next.js root as a map of relative paths
 * (from `.portosaur/`) to file contents.
 *
 * The route files are mode-aware, matching the frozen URL inventory:
 * docs mode generates the `app/docs/` detail routes (the notes
 * collection IS the docs collection there, so the `app/notes/` detail
 * routes are skipped). Portfolio mode generates the `app/notes/`
 * detail routes and no `app/docs/` routes at all. The notes index
 * (`app/notes/page.tsx`) exists in both modes, which is why the notes
 * detail route is a required catch-all (`[...slug]`) while the docs
 * one is optional (`[[...slug]]`) — see `buildDocPageContent`. The
 * blog index and
 * authors pages always exist. Only the `/blog/[slug]` post route
 * needs at least one post (see `NextRootArgs.hasBlogPosts`).
 */
export function buildNextRootFiles(
  options: PortosaurOptions,
  args: NextRootArgs,
): Record<string, string> {
  const { mtime } = args;

  const files: Record<string, string> = {
    "next.config.mjs": buildNextConfigContent(options, args),
    "source.config.ts": buildSourceConfigContent(options, mtime),
    "lib/source.ts": buildLibSourceContent(options, mtime),
    "lib/config.ts": buildLibConfigContent(options, mtime),
    "lib/blog.ts": buildLibBlogContent(mtime),
    "postcss.config.mjs": buildPostcssConfigContent(mtime),
    "tsconfig.json": buildTsConfigContent(args),
    "next-env.d.ts": buildNextEnvContent(),
    "app/layout.tsx": buildRootLayoutContent(options, args),
    "app/page.tsx": buildHomePageContent(options, mtime),
    "app/notes/page.tsx": buildNotesIndexContent(mtime),
    "app/tasks/page.tsx": buildTasksPageContent(options, mtime),
    "app/blog/page.tsx": buildBlogIndexContent(mtime),
    "app/blog/authors/page.tsx": buildBlogAuthorsContent(mtime),
    "app/search/page.tsx": buildSearchPageContent(mtime),
    "app/offline/page.tsx": buildOfflinePageContent(mtime),
    "app/redirect/page.tsx": buildRedirectPageContent(mtime),
    "app/not-found.tsx": buildNotFoundContent(mtime),
    "app/api/search/route.ts": buildSearchRouteContent(mtime),
    "app/sitemap.ts": buildSitemapContent(mtime),
    "app/robots.ts": buildRobotsContent(mtime),
    "app/llms.txt/route.ts": buildLlmsTxtRouteContent(mtime),
    "app/llms-full.txt/route.ts": buildLlmsFullTxtRouteContent(mtime),
    "app/llms.mdx/[...path]/route.ts": buildLlmsMdxRouteContent(mtime),
  };

  if (options.site.pwa?.enable !== false) {
    files["app/manifest.ts"] = buildManifestContent(mtime);
  }

  if (options.siteMode === "docs") {
    files["app/docs/layout.tsx"] = buildDocsLayoutContent(mtime);
    files["app/docs/[[...slug]]/page.tsx"] = buildDocPageContent("docs", mtime);
  } else {
    // The detail routes live in a route group so the docs layout
    // (sidebar + shell) wraps ONLY them: a layout at
    // `app/notes/layout.tsx` would wrap the index too, and the
    // index renders its own shell — double navbar, double footer,
    // and a sidebar the index must not have. Route groups don't
    // affect URLs, so the pages still serve at `/notes/<slug>`.
    files["app/notes/(with-sidebar)/layout.tsx"] =
      buildDocsLayoutContent(mtime);
    files["app/notes/(with-sidebar)/[...slug]/page.tsx"] = buildDocPageContent(
      "notes",
      mtime,
      "required",
    );
  }

  // Only the post route needs a post: the index and authors pages
  // are static routes that render their empty state.
  if (args.hasBlogPosts) {
    files["app/blog/[slug]/page.tsx"] = buildBlogPostContent(mtime);
  }

  return files;
}
